import { createS3Client, type GetObjectOutput, GetObjectCommand } from "aws-s3-v2";

/**
 * Leaf I/O only — AWS SDK v2 getObject().promise().
 * Callers live in app.ts (separate file / DFG edge).
 */
const s3 = createS3Client();

export function fetchObjectBody(
  bucket: string,
  key: string
): Promise<string> {
  return s3.send(new GetObjectCommand({ Bucket: bucket, Key: key })).then((result: GetObjectOutput) => {
    return result.Body;
  });
}

export function loadBanner(bucket: string): Promise<string> {
  return s3
    .send(new GetObjectCommand({ Bucket: bucket, Key: "banner.txt" }))
    .then((body: GetObjectOutput) => body.Body);
}
